package java.util;
public class ArrayDeque<E> extends AbstractCollection<E> implements Deque<E>,Cloneable,java.io.Serializable {
 private final LinkedList<E> list=new LinkedList<E>();public ArrayDeque(){}public ArrayDeque(int n){if(n<0)throw new IllegalArgumentException();}public ArrayDeque(Collection<? extends E> c){addAll(c);}public int size(){return list.size();}public Iterator<E> iterator(){return list.iterator();}public Iterator<E> descendingIterator(){return list.descendingIterator();}public void addFirst(E e){list.addFirst(Objects.requireNonNull(e));}public void addLast(E e){list.addLast(Objects.requireNonNull(e));}public boolean offerFirst(E e){addFirst(e);return true;}public boolean offerLast(E e){addLast(e);return true;}public boolean add(E e){addLast(e);return true;}public boolean offer(E e){return offerLast(e);}public E removeFirst(){return list.removeFirst();}public E removeLast(){return list.removeLast();}public E pollFirst(){return list.pollFirst();}public E pollLast(){return list.pollLast();}public E getFirst(){return list.getFirst();}public E getLast(){return list.getLast();}public E peekFirst(){return list.peekFirst();}public E peekLast(){return list.peekLast();}public boolean removeFirstOccurrence(Object o){return list.removeFirstOccurrence(o);}public boolean removeLastOccurrence(Object o){return list.removeLastOccurrence(o);}public E remove(){return removeFirst();}public E poll(){return pollFirst();}public E element(){return getFirst();}public E peek(){return peekFirst();}public void push(E e){addFirst(e);}public E pop(){return removeFirst();}public void clear(){list.clear();} }
